def save(p,v):p.write_text(json.dumps(v,ensure_ascii=False,indent=2,allow_nan=False)+'\n',encoding='utf8')
def main():
    signals=read(OUT/'numpy_analysis/summary.json');verification=read(OUT/'download_and_gradient_verification.json');trace=read(OUT/'localization_trace/summary.json');observations=read(OUT/'terminal_and_resource_observations.json')
    assert verification['status'].startswith('PASS_BOTH') and trace['status'].startswith('PASS_FIXED')
    for r in observations:assert f"MATCHED_SEED{r['seed']}_EXIT=0" in r['output'] and '2 MiB, 0 %' in r['output']
    primary=[r for r in signals['primary_unsaturated_final_by_size'] if r['endpoint']==132 and r['input_size_bin']=='lt4'];assert [r['matched_rows'] for r in primary]==[1737,1826]
    well=[r for r in signals['strata'] if r['endpoint']==132 and r['dimension']=='unsaturated_tiny_stage_quality' and r['value']=='model / ge75'];assert sum(r['matched_rows'] for r in well)==75 and all(r['margin_down']==0 for r in well)
    final=[r for r in trace['primary_unsaturated_tiny_mature'] if r['stage']=='model']
    nearest=[];papers=ROOT/'英文小论文/文献_相关原始论文_20261004'
    for name,status,url,note in [
      ('14_DEIM_CVPR2025_improved-matching.pdf','CVPR2025 main','https://openaccess.thecvf.com/content/CVPR2025/html/Huang_DEIM_DETR_with_Improved_Matching_for_Fast_Convergence_CVPR_2025_paper.html','Baseline MAL intentionally calibrates matching IoU and uses DenseO2O augmentation; observed low-IoU score reduction is not a new mechanism or code bug.'),
      ('105_D_FINE_ICLR2025_Publisher.pdf','ICLR2025 publisher','https://openreview.net/forum?id=MFZjrTFE7h','Baseline already has FDR and differentiable LQE. Native shared scalar cannot alter within-query logit margin directly; adding a quality head is not an unoccupied idea.'),
      ('22_NWD_tiny-object__arXiv-2110.13389.pdf','Historical 2021 preprint; related2022 ISPRS article, outside recent-two-year main corpus','https://arxiv.org/abs/2110.13389','Scale sensitivity of IoU for tiny boxes is established precedent; merely replacing IoU by NWD would not establish a substantive new mechanism. No such change implemented.'),
      ('01_CLSC_DETR_2026_UAV_candidate_ranking__arXiv-2608.21457.pdf','2026 arXiv preprint, no verified TOP/main-conference status','https://arxiv.org/abs/2608.21457','Cross-layer geometric evidence and ranking calibration already proposed. Full300 final queries have only270/228 geometric IoU>=.5 exposures in this augmentation stratum, so ranking alone has limited geometric supply; not a replication of its AP claims.')]:
        p=papers/name;assert p.is_file();nearest.append(dict(file=str(p),sha256=sha(p),verified_publication_status=status,primary_url=url,relevance=note,download_action='existing canonical local PDF retained, no duplicate'))
    next_action='Discriminate full encoder candidate supply from discrete TopK selection before changing attention or losses: capture the unchanged native full encoder class-logit pool, exact selected indices, and diagnostic full-pool enc_bbox_head predictions on a prospective fixed augmented + ordinary-validation panel, at BASE12/132. Check whether unselected candidates actually contain accurate tiny boxes. Same-query trace of selected outputs alone cannot identify whether backbone representation, encoder regression or TopK is responsible. Freeze budget/source/protocol first; no automatic training, no revival of closed reclassification/ROI/range routes.'
    decision={'status':'MAL_IMPLEMENTATION_VERIFIED_SELECTED_PROPOSAL_GEOMETRY_GAP_OBSERVED_CAUSE_UNRESOLVED','GT_score_suppression_bug_supported':False,'well_localized_weak_score_wrong_direction_supported':False,'classification_effect_on_training_or_AP_established':False,'selected_query_geometry_gap_observed':True,'all_encoder_pool_measured':False,'encoder_or_backbone_or_TopK_root_cause_established':False,'detector_training_launched':False,'new_AP_result':False,'primary_MAL':primary,'well_localized_tiny_control':well,'primary_final_geometry':final,'next':next_action,'closed_routes_remain_closed':True,'normal_capacity_prior_gate_unchanged':False}
    save(OUT/'decision.json',decision)
    fallacies={
      '1_Simpson':'Seeds/endpoints/size/quality/stage/MixUp/class/density retained separately; no pooling into an AP effect.',
      '2_Ecological':'Exposure and fixed-query output rows are descriptive units, not independent observations or parameter-gradient effects.',
      '3_Berkson':'Augmentation survival, final matching and GT<=300 are explicit selected strata. Not whole dataset/training prevalence.',
      '4_Collider':'Matching and quality strata depend on predictions; conditioning can couple classification and geometry. No causal attribution.',
      '5_Base_rates':'Raw denominators and IoU thresholds preserved. Matched IoU/class argmax/any-query geometry are not AP/recall/TP metrics.',
      '6_Regression_to_mean':'No intervention tested and no selected early/best epoch improvement claim; fixed BASE12/132 descriptive snapshots only.',
      '7_Survivorship':'All320 original normal MAL calls and all5 stages retained; both CPU runs exit0; no retry or posthoc sample exclusion.',
      '8_Look_elsewhere':'Many past routes remain disclosed/closed. All predeclared strata retained; component trace is separately frozen exploratory follow-up after MAL.',
      '9_Forking_paths':'Original MAL protocol precedes computation; separate geometry protocol frozen before component outcomes. No AP success gate or primary stratum changed.',
      '10_Correlation_causation':'Native leaf differentiation proves loss algebra, not harmful model updates. GT center/size substitutions are infeasible output oracles, not causal model interventions.',
      '11_Reverse_causality':'Poor localization can cause intended score calibration; current frozen EMA train-mode augmentations are not the original learning trajectory. Initial selected boxes weak does not prove selector caused the weakness.'}
    validation={'material_passport':{'skill':'academic-research-suite','workflow':'experiment-agent','mode':'run+validate','verification_status':'ANALYZED_SCIENTIFIC_SCOPE_WITH_VERIFIED_NATIVE_LEAF_AUTOGRAD_AND_SAVED_ARRAY_RECOMPUTATION'},'observed_local_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'native_verification':verification,'localization_verification':{k:v for k,v in trace.items() if k not in ['primary_unsaturated_tiny_mature','all_unsaturated_size_endpoint_stages','final_oracle_joint_categories','encoder_final_crossings']},'fallacy_scan':{'checked':11,'total':11,'items':fallacies},'decision':decision,'nearest_precedents':nearest,'limitations':read(OUT/'protocol.json')['limitations']+['Only selected300 encoder candidate boxes were archived originally; all encoder memory candidates remain unmeasured.','Augmented fixed epoch4 train-mode FP32 EMA fixtures may not reflect ordinary native validation or actual132 optimizer dynamics.','GT center and size oracle categories interact; neither single substitution rescues most75 failures. They do not identify a trainable correction.'],'no_detector_AP_experiment':True,'no_accepted_new_mechanism':True}
    save(OUT/'validation_report.json',validation)
    text=['已匹配微小目标：损失信号与定位阶段核对','', '范围：既有64个增强batch、两个seed、BASE12/132；每张4图。重点是每张组合图GT≤300、输入短边<4px的成熟权重输出。这不是全量验证AP或真实训练历史。','', '1. 原生MAL与梯度已核验']
    text+=['320次CPU叶子logit自动求导；原生全部384万个梯度坐标与解析式核对，本地另比对344360个匹配GT/最大其他类别梯度。','NumPy重算原生MAL最大误差1.3123e-7；CPU/CUDA原始损失最大差1.7881e-7；本地与原生匹配梯度最大差6.5507e-10。两归档SHA及14份文件通过。','MAL正类目标是detach(IoU)^1.5，背景权重也detach。正类分数下降不等于类别分数差下降；两者分别记录。LQE已有共享质量标量，IoU目标detach不等于回归分布完全没有来自LQE的分类梯度。','']
    text+=['2. 成熟权重中已匹配微小目标的真实数字','seed | 目标曝光 | 平均匹配IoU | GT分数下降 | GT减最大其他类logit分差下降 | IoU≥.75']
    for r in primary:text.append(f"{r['seed']} | {r['matched_rows']} | {r['mean_IoU']:.6f} | {r['GT_score_down']}/{r['matched_rows']} ({100*r['fraction_GT_score_down']:.2f}%) | {r['margin_down']}/{r['matched_rows']} ({100*r['fraction_margin_down']:.2f}%) | {r['IoU_ge75']}")
    text+=['同一主范围内IoU≥.75的43+32=75个微小匹配目标，类别分差全部向上。所有阶段/端点336个IoU≥.75且GT分数<.05的匹配曝光，也全部向上；这一方向与损失公式相符。','故不能把低IoU目标被压分直接判为MAL错误；损失会刻意压低定位差的候选。这未证明不需要更好的分类监督，但不足以据此开训。','', '3. 同一最终query沿各输出阶段追踪（没有换query制造改善）','seed | 编码器所选候选IoU≥.5 | 最终IoU≥.5 | 最终全部300query中有IoU≥.5候选 | 总曝光']
    initial=[r for r in trace['primary_unsaturated_tiny_mature'] if r['stage']=='model.enc_aux_outputs.0']
    for a,b in zip(initial,final):text.append(f"{a['seed']} | {a['pair_ge50']} | {b['pair_ge50']} | {b['any_query_ge50']} | {a['rows']}")
    text+=['已有缺口出现在编码器所选候选框输出，解码器有改善但多数目标仍没有几何准确的候选；并非已定位准确后普遍被分类损失压低。这里不能据此判定主干、编码器回归或TopK哪个是根因，因为完整未选候选池尚未保存。','pre_outputs由第0层decoder处理后再经pre_bbox_head得到，不能称为decoder入口。源码确认5阶段普通query序号对应；34436个最终匹配IoU与原生数组完全一致。','仅把GT中心或GT尺寸代入最终框，在IoU .75失败的1694/1794个曝光中，两种单独替换都不能救回1506/1616个；中心和尺寸问题共同存在。这是使用GT的几何诊断，不能部署或称为AP提升。','', '4. 本轮成本与判定','新增模型前向0、模型反向0、优化器0、训练0轮。两个CPU核验37.69/26.68秒；两个任务exit0，原进程句柄消失，最后远端UTC09:07:50两GPU2MiB/0%。','没有新的AP/APs/AP75实验结果，也未接受新机制或确认网络根因。12轮上限、固定12EMA与同seed BASE比较、APs增加且整体AP不降的规则保持。','下一步：区分完整编码器候选池能否产生正确微小框、这些框是否被TopK漏选；同时保留普通验证图对照，避免只从早期增强fixture推断常规检测错误。先冻结采集协议，不恢复被淘汰路线。','', '证据路径：protocol.json；download_and_gradient_verification.json；numpy_analysis/summary.json与per_match_signals.csv；localization_followup_protocol.json；localization_trace/summary.json与per_fixed_query_stage_geometry.csv；validation_report.json；decision.json；collection_seed1/2。','已有DEIM、D-FINE、NWD及CLSC PDF已核对SHA，保留本地单份；CLSC是2026预印本，NWD为历史近邻，不冒充近期顶会/一区TOP新作。','科研统计11/11误区扫描完成。目标仍进行中。']
    (OUT/'结论与证据索引.txt').write_text('\n'.join(text)+'\n',encoding='utf8')
    manifest={str(p.relative_to(OUT)):sha(p) for p in OUT.rglob('*') if p.is_file() and not p.parts[-2].startswith('transfer_seed') and p.name!='delivery.json'}
    delivery={'status':'COMPLETE_NATIVE_MAL_AND_FIXED_QUERY_LOCALIZATION_DIAGNOSTIC_VERIFIED','observed_local_utc':validation['observed_local_utc'],'material_passport':validation['material_passport'],'code':str(Path(__file__).parent),'all_code_sha256':{p.name:sha(p) for p in Path(__file__).parent.glob('*.py')},'output_manifest_sha256':manifest,'native_verification':verification,'decision':decision,'scientific_goal_status':'active','new_detector_training_epochs':0,'new_AP_result':False}
    save(OUT/'delivery.json',delivery)
    statepath=ROOT/'outputs/sod_roi12_20261009/execution_state.json';state=read(statepath)
    state['status']='PROBLEM_DRIVEN_RESEARCH_ACTIVE_NATIVE_MAL_AND_SELECTED_PROPOSAL_TRACE_VERIFIED';state['goal_status']='active'
    state['last_goal_turn_classification']='PROGRESS: froze and completed archived320normalMAL reconstruction + both native CPU autograd jobs exit0; downloaded SHAverified archives, verified344360matched gradients. Separately froze and completed172180fixed-query geometry rows;34436native finalIoUs exact. Well-localized tiny control75/75 correct margin upward; geometric deficit already present among selected encoder boxes. Full encoder supply vs TopK remains unmeasured.'
    state['matched_quality_signal_diagnostic']={'status':delivery['status'],'delivery':str(OUT/'delivery.json'),'human_report':str(OUT/'结论与证据索引.txt'),'primary_MAL':primary,'well_localized_tiny_control':well,'final_geometry':final,'native_leaf_backward_calls':320,'model_forward_calls':0,'model_backward_calls':0,'training_epochs_added':0,'optimizer_steps':0,'AP_evidence':False,'root_cause_established':False}
    state['current_research_iteration']={'status':'MAL_AND_SELECTED_PROPOSAL_GEOMETRY_DIAGNOSTIC_COMPLETE','decision':str(OUT/'decision.json'),'next':next_action}
    state['research_iteration_history'].append({'status':delivery['status'],'delivery':str(OUT/'delivery.json'),'epochs_added':0,'new_AP_result':False})
    state['next']=next_action;state['updated_utc']=validation['observed_local_utc'];save(statepath,state)
    with (ROOT/'outputs/sod_roi12_20261009/continuation_state.txt').open('a',encoding='utf8') as f:f.write('\n'+validation['observed_local_utc']+' Authoritative: '+state['last_goal_turn_classification']+'\nNext: '+next_action+'\nOverall goal ACTIVE, no detector training/AP success.\n')
    print(json.dumps({'status':delivery['status'],'primary':primary,'well_localized_control_count':75,'final_geometry':final,'AP_evidence':False,'epochs_added':0,'goal_status':'active'}))
